// All Lucide icons with categories and search tags — a separate chunk, loaded on first use
// (icon picker, or a note with an icon outside the common set in icons.tsx).
import { icons } from 'lucide-react';
import meta from './lucide-meta.json';

export { icons };

/** Generated by scripts/lucide-meta.mjs: name → [category indexes, search tags]. */
export const categories: { id: string; title: string }[] = meta.categories;
export const iconMeta = meta.icons as unknown as Record<string, [number[], string]>;

/** `arrow-down-0-1` → `ArrowDown01` (the export name in lucide-react). */
export const pascal = (name: string) => name.replace(/(^|-)([a-z0-9])/g, (_, __, c: string) => c.toUpperCase());
